@namespace sv_cc9cad0d16fe4c149614cfe0c0fbc7aa.Components.Pages.Settings
@using sv_cc9cad0d16fe4c149614cfe0c0fbc7aa.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label><strong>Theme</strong></label>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label><strong>Font Size</strong></label>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language"><strong>Language</strong></label>
            <select id="language" @bind="_language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="form-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" />
                <span><strong>Compact Mode</strong></span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <strong>Sample Card</strong>
                <p>A preview of card content with your chosen appearance options applied.</p>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

